from extract import *
p=json.loads(P.read_text())
for s,y in zip(p['fig_03.png'],[3.0095,2.3031,.4654,.2426]):
 s['data'].append({'x':2015.931,'y':y});s['data'].sort(key=lambda v:v['x'])
save(3,p['fig_03.png'])
print('green 16 x:',[round(q['x'],2) for q in p['fig_16.png'][3]['data']])
for q in p['fig_30.png'][0]['data']:q['x']=max(0,q['x']);q['y']=max(0,q['y'])
save(30,p['fig_30.png'])
# Validate every image key and the required point schema.
p=json.loads(P.read_text())
assert set(p)=={f.name for f in Path('images').glob('*.png')}
assert len(p)==30
for ss in p.values():
 for s in ss:
  assert isinstance(s['name'],str) and s['name']
  for q in s['data']:assert set(q)=={'x','y'} and all(np.isfinite(v) for v in q.values())
print('Validated 30 charts;',sum(len(s['data']) for ss in p.values() for s in ss),'points')
PY"

